CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member' CHECK(role IN('member','author','admin')),genres TEXT DEFAULT '[]',blocked INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS books(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT UNIQUE NOT NULL,author TEXT NOT NULL,genre TEXT NOT NULL,featured INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS reading_groups(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,book_id INTEGER NOT NULL REFERENCES books(id),is_public INTEGER DEFAULT 1,goal TEXT,lead_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS group_members(group_id INTEGER REFERENCES reading_groups(id),user_id INTEGER REFERENCES users(id),role TEXT DEFAULT 'member',status TEXT DEFAULT 'active' CHECK(status IN('active','pending')),PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS threads(id INTEGER PRIMARY KEY AUTOINCREMENT,group_id INTEGER NOT NULL REFERENCES reading_groups(id),author_id INTEGER NOT NULL REFERENCES users(id),category TEXT,title TEXT NOT NULL,body TEXT NOT NULL,removed INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY AUTOINCREMENT,thread_id INTEGER NOT NULL REFERENCES threads(id),parent_id INTEGER REFERENCES comments(id),author_id INTEGER NOT NULL REFERENCES users(id),body TEXT NOT NULL,removed INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,book_id INTEGER NOT NULL REFERENCES books(id),user_id INTEGER NOT NULL REFERENCES users(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),text TEXT,UNIQUE(book_id,user_id));
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY AUTOINCREMENT,thread_id INTEGER REFERENCES threads(id),comment_id INTEGER REFERENCES comments(id),reporter_id INTEGER NOT NULL REFERENCES users(id),reason TEXT,status TEXT DEFAULT 'open');
